-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich als ITler ohne klare Ziele erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele geben Orientierung"}, {"text": "Ja", "correct": false, "because": "Ohne Plan schwierig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ich mich als Azubi schon auf eine Spezialisierung festlegen?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibilität bleibt"}, {"text": "Ja", "correct": false, "because": "Später möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Weiterbildung für eine IT-Karriere Pflicht?', 2, '[{"text": "Ja", "correct": true, "because": "Technik entwickelt sich ständig"}, {"text": "Nein", "correct": false, "because": "Stillstand ist riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich ohne Weiterbildung Teamleiter werden?', 2, '[{"text": "Nein", "correct": true, "because": "Fähigkeiten müssen aktuell sein"}, {"text": "Ja", "correct": false, "because": "Qualifikation oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Sind Zertifikate wie Cisco für Weiterbildung wichtig?', 2, '[{"text": "Ja", "correct": true, "because": "Sie steigern die Kompetenz"}, {"text": "Nein", "correct": false, "because": "Arbeitgeber schätzen sie"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ich meine Berufsziele ohne Chef absprechen?', 2, '[{"text": "Ja", "correct": true, "because": "Persönliche Planung ist frei"}, {"text": "Nein", "correct": false, "because": "Abstimmung hilft aber"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Hochschulstudium als Weiterbildung für ITler nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Praxis zählt oft mehr"}, {"text": "Ja", "correct": false, "because": "Alternativen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich mich ohne Ziele auf eine Beförderung vorbereiten?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele steuern den Weg"}, {"text": "Ja", "correct": false, "because": "Planlosigkeit hemmt"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel ist für einen IT-Azubi realistisch?', 2, '[{"text": "Fachwissen vertiefen", "correct": true, "because": "Grundlage für Karriere"}, {"text": "CEO werden", "correct": false, "because": "Zu früh"}, {"text": "Urlaub planen", "correct": false, "because": "Kein Berufsziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin will, dass ich mich weiterbilde. Was wähle ich für Netzwerke?', 3, '[{"text": "CCNA", "correct": true, "because": "Cisco-Zertifikat für Netzwerke"}, {"text": "Photoshop-Kurs", "correct": false, "because": "Design, kein IT"}, {"text": "Excel-Schulung", "correct": false, "because": "Büro, kein Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Weiterbildung hilft mir als ITler langfristig?', 2, '[{"text": "Cloud-Zertifikat", "correct": true, "because": "Zukunftstrend"}, {"text": "Schreibkurs", "correct": false, "because": "Wenig IT-Bezug"}, {"text": "Kochkurs", "correct": false, "because": "Kein Berufsbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt nach meinem Ziel. Was sage ich?', 3, '[{"text": "Spezialisierung in Sicherheit", "correct": true, "because": "Klar und realistisch"}, {"text": "Millionär werden", "correct": false, "because": "Zu vage"}, {"text": "Nichts ändern", "correct": false, "because": "Kein Ehrgeiz"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Ziele könnten IT-Azubis haben?', 4, '[{"text": "Fachwissen aufbauen", "correct": true, "because": "Basis für Karriere"}, {"text": "Teamleitung anstreben", "correct": true, "because": "Langfristig möglich"}, {"text": "Zertifikate sammeln", "correct": true, "because": "Steigert Wert"}, {"text": "Weniger arbeiten", "correct": false, "because": "Kein Berufsziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu einer guten Weiterbildungsplanung?', 3, '[{"text": "Relevanz prüfen", "correct": true, "because": "Muss Job passen"}, {"text": "Zeitplan machen", "correct": true, "because": "Struktur nötig"}, {"text": "Kosten klären", "correct": true, "because": "Finanzierbarkeit"}, {"text": "Urlaub buchen", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir wollen uns als Team weiterbilden. Was passt für IT?', 3, '[{"text": "Programmierkurs", "correct": true, "because": "Technische Skills"}, {"text": "Netzwerktraining", "correct": true, "because": "Systemkompetenz"}, {"text": "Projektmanagement", "correct": true, "because": "Koordination"}, {"text": "Kunstkurs", "correct": false, "because": "Kein IT-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Weiterbildungen sind für ITler gefragt?', 4, '[{"text": "Cybersecurity", "correct": true, "because": "Wachsende Nachfrage"}, {"text": "Cloud Computing", "correct": true, "because": "Aktueller Trend"}, {"text": "ITIL", "correct": true, "because": "Prozessoptimierung"}, {"text": "Yoga", "correct": false, "because": "Kein IT-Thema"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ziele sollten spezifisch sein. b) Weiterbildung ist nur für Führungskräfte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Spezifität ja, Weiterbildung für alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Weiterbildung kostet immer Geld. b) Berufsziele ändern sich nie.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Kostenlos möglich, Ziele wandelbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Ziel könnte sein, Cloud-Experte zu werden. b) Weiterbildung ist nur in der Freizeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ziel realistisch, Weiterbildung auch beruflich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zertifikate helfen bei der Jobsuche. b) Ohne Ziele keine Weiterbildung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zertifikate nützlich, Weiterbildung auch ohne Ziele"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

